package com.yongdrel.bulk_verification_service.adapter.in.web;
import com.yongdrel.bulk_verification_service.adapter.out.persistence.*; import com.yongdrel.bulk_verification_service.application.service.BulkVerificationService; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.*;
@RestController @RequestMapping("/api/bulk-verifications") public class BulkVerificationController{private final BulkVerificationService service;public BulkVerificationController(BulkVerificationService s){service=s;}@PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public BatchResponse submit(@RequestPart String idempotencyKey,@RequestPart MultipartFile file,Authentication a){VerificationBatchEntity b=service.submit(claim(a,"tenant_id"),claim(a,"sub"),idempotencyKey,file);return new BatchResponse(b.getId(),b.getSubmittedAt());}@GetMapping("/{id}")public List<ItemResponse> results(@PathVariable UUID id,Authentication a){return service.results(id,claim(a,"tenant_id")).stream().map(x->new ItemResponse(x.getReference(),x.getResult().name(),x.getPaymentId(),x.getProcessedAt())).toList();}private static UUID claim(Authentication a,String n){if(!(a.getPrincipal() instanceof Jwt j))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED,"Trusted JWT required");try{return UUID.fromString(j.getClaimAsString(n));}catch(Exception e){throw new org.springframework.web.server.ResponseStatusException(HttpStatus.FORBIDDEN,"Required UUID claim missing");}}public record BatchResponse(UUID batchId,java.time.Instant submittedAt){}public record ItemResponse(String reference,String result,UUID paymentId,java.time.Instant processedAt){}}
